Video* newVideo()
{
	return calloc(1, sizeof(Video));
}

static void updateVideoOutputs(Video* v)
{
	/* All PIA port A control lines are active low; input pins pull high. */
	unsigned int pins = v->io | (~v->ddrA & 0xff);
	v->redenabled = !(pins & 1); v->greenenabled = !(pins & 2);
	v->blueenabled = !(pins & 4); v->flashenabled = !(pins & 8);
	v->redcopy = !(pins & 16); v->greencopy = !(pins & 32);
	v->bluecopy = !(pins & 64); v->vramenabled = !(pins & 128);
}

static int clearScreenActive(const Video* v)
{
	/* 6821 C2 manual output low: control bits 5..3 = 110. */
	return (v->controlA & 0x38) == 0x30;
}

static void clearVideo(Video* v)
{
	if(clearScreenActive(v)) {
		unsigned int fill = (v->controlB & 8) ? 0xff : 0;
		for(unsigned int i = 0; i < 0x30000; i++) v->vram[i] = fill;
	}
}

void resetVideo(Video* v, unsigned int* pixels)
{
	memset(v, 0, sizeof(*v));
	memset(pixels, 0, VWIDTH * VHEIGHT * sizeof(*pixels));
	updateVideoOutputs(v);
}

unsigned int videoMemoryAddress(const Video* v, unsigned int offset)
{
	/* VRMM PROM 444-127 maps the 80 visible bytes of each 128-byte CPU
	   scan line contiguously, followed by the 48 hidden bytes in a separate
	   area. The start latch adds to physical address bits 8..15. */
	unsigned int row = (offset >> 11) & 31;
	unsigned int column = (offset >> 4) & 7;
	unsigned int mapped = column < 5 ? row * 5 + column : 160 + row * 3 + column - 5;
	unsigned int latch = v->addressLatch | (~v->ddrB & 255);
	return (offset & 0x30000) | (((mapped + latch) & 255) << 8)
		| ((offset & 15) << 4) | ((offset >> 7) & 15);
}

unsigned int videoMemoryRead(Video* v, unsigned int offset)
{
	if(offset >= 0x30000 || !v->vramenabled) return 0xff;
	return v->vram[videoMemoryAddress(v, offset)] & 0xff;
}

void videoMemoryWrite(Video* v, unsigned int offset, unsigned int data)
{
	if(offset >= 0x30000 || !v->vramenabled) return;
	offset = videoMemoryAddress(v, offset);
	/* Approximate the continuous CRT clear by applying its polarity on writes
	   while asserted, in addition to filling the planes on assertion. */
	if(clearScreenActive(v)) data = (v->controlB & 8) ? 0xff : 0;
	v->vram[offset] = data & 0xff;
	offset &= 0xffff;
	if(v->bluecopy) v->vram[offset] = data & 0xff;
	if(v->redcopy) v->vram[offset + 0x10000] = data & 0xff;
	if(v->greencopy) v->vram[offset + 0x20000] = data & 0xff;
}

unsigned int readVideo(Video* v, unsigned int addr)
{
	switch(addr) {
	case 0xd8: return (v->controlA & 4) ? (v->io | (~v->ddrA & 255)) : v->ddrA;
	case 0xd9: return v->controlA;
	case 0xda: return (v->controlB & 4) ? (v->addressLatch | (~v->ddrB & 255)) : v->ddrB;
	case 0xdb: return v->controlB;
	case 0xdc: return v->registerPointer;
	case 0xdd: return v->registerPointer < 18 ? v->registers[v->registerPointer] : 0;
	}
	return 0;
}

void writeVideo(Video* v, unsigned int addr, unsigned int data)
{
	data &= 255;
	switch(addr) {
	case 0xd8:
		if(v->controlA & 4) v->io = data; else v->ddrA = data;
		updateVideoOutputs(v);
		break;
	case 0xd9: {
		int was_clear = clearScreenActive(v);
		v->controlA = data & 0x3f;
		if(!was_clear) clearVideo(v);
		break;
	}
	case 0xda:
		if(v->controlB & 4) v->addressLatch = data; else v->ddrB = data;
		break;
	case 0xdb:
		v->controlB = data & 0x3f;
		clearVideo(v);
		break;
	case 0xdc:
		v->registerPointer = data & 31;
		break;
	case 0xdd:
		if(v->registerPointer >= 18) break;
		v->registers[v->registerPointer] = data;
		if(v->registerPointer == 14) v->cursorh = data & 63;
		if(v->registerPointer == 15) v->cursorl = data;
		if(v->registerPointer == 10) v->cursors = data;
		if(v->registerPointer == 11) v->cursore = data;
		break;
	}
}

static unsigned int displayStart(const Video* v)
{
	return ((v->registers[12] & 63) << 8) | v->registers[13];
}

void renderScreen(Video* v, unsigned int* pixels)
{
	memset(pixels, 0, VWIDTH * VHEIGHT * sizeof(*pixels));
	unsigned int columns = v->registers[1];
	unsigned int rows = v->registers[6];
	unsigned int height = (v->registers[9] & 15) + 1;
	unsigned int start = displayStart(v);
	unsigned int cursor = ((v->cursorh & 63) << 8) | v->cursorl;
	unsigned int mode = (v->cursors >> 5) & 3;
	int cursor_on = mode == 0 || (mode == 2 && !(v->frames & 16)) ||
		(mode == 3 && !(v->frames & 32));
	for(unsigned int y = 0; y < VHEIGHT && y / height < rows; y++) {
		unsigned int ra = y % height;
		for(unsigned int x = 0; x < columns && x < VWIDTH / 8; x++) {
			unsigned int ma = (start + (y / height) * columns + x) & 0x3fff;
			unsigned int address = ((ma & 0xfff) << 4) | ra;
			int cursor_here = cursor_on && ma == cursor && ra >= (v->cursors & 31) && ra <= (v->cursore & 31);
			for(unsigned int bit = 0; bit < 8; bit++) {
				unsigned int blue = (v->vram[address] >> (7 - bit)) & 1;
				unsigned int red = (v->vram[address + 0x10000] >> (7 - bit)) & 1;
				unsigned int green = (v->vram[address + 0x20000] >> (7 - bit)) & 1;
				if(cursor_here) { blue ^= 1; red ^= 1; green ^= 1; }
				if(v->flashenabled) blue = red = green = 1;
				pixels[y * VWIDTH + x * 8 + bit] =
					((red && v->redenabled) ? 0xff0000 : 0) |
					((green && v->greenenabled) ? 0x00ff00 : 0) |
					((blue && v->blueenabled) ? 0x0000ff : 0);
			}
		}
	}
}

unsigned int* generateScreen()
{
	// make an usigned int array of size that takes into account the resolution
	// of the Z-100 screen (640 X 225 pixels). VWIDTH and VHEIGHT are defined
	// in video.h (VWIDTH = 640, VHEIGHT = 225).
	unsigned int* pixels = (unsigned int*)malloc((VWIDTH)*(VHEIGHT)*sizeof(unsigned int));
	for(int y=0; y<VHEIGHT; y++)
	{
		for(int x=0; x<VWIDTH; x++)
		{
			// set each element in the array to 0. Each element represents one pixel
			// on the screen
			pixels[VWIDTH*y+x]=0;
		}
	}
	// return the unsigned int array
	return pixels;
}

void drawASCII(unsigned int* pixels)
{
	printf("\33c");
	for(int y=0; y<VHEIGHT; y++)
	{
		for(int x=0; x<VWIDTH; x++)
		{
			if(pixels[VWIDTH*y+x]!=0)
				printf("*");
			else
				printf(" ");
		}
		printf("\n");
	}
}

void videoWrite(Video* v, int code)
{
	int x = v->x, y = v->y;
	if(v->esc == 2) { v->escline = code - ' '; v->esc = 3; return; }
	if(v->esc == 3) { x = code - ' '; y = v->escline; v->esc = 0; }
	else if(v->esc == 1) {
		v->esc = 0;
		if(code == 'Y') { v->esc = 2; return; }
		if(code == 'H') x = y = 0;
		if(code == 'E' || code == 'J') {
			memset(v->vram + 0x20000, 0, 0x10000 * sizeof(*v->vram)); x = y = 0;
		}
	}
	else if(code >= 0x20 && code <= 0x7e) { videoSetChar(v, x, y, code); if(x < 79) x++; }
	else if(code == 8) { if(x > 0) x--; }
	else if(code == '\r') x = 0;
	else if(code == 0x1b) v->esc = 1;
	else if(code == '\n') {
		if(y < 24) y++;
		else {
			/* This is software terminal scrolling, not the hardware start latch. */
			unsigned int start = displayStart(v);
			for(unsigned int cell = 0; cell < 24 * 80; cell++)
				for(unsigned int line = 0; line < 16; line++)
					v->vram[0x20000 + (((start + cell) & 0xfff) << 4) + line] =
						v->vram[0x20000 + (((start + cell + 80) & 0xfff) << 4) + line];
			for(unsigned int cell = 24 * 80; cell < 25 * 80; cell++)
				for(unsigned int line = 0; line < 16; line++)
					v->vram[0x20000 + (((start + cell) & 0xfff) << 4) + line] = 0;
		}
	}
	if(x < 0) x = 0; if(x > 79) x = 79;
	if(y < 0) y = 0; if(y > 24) y = 24;
	unsigned int cursor = (displayStart(v) + y * 80 + x) & 0x3fff;
	v->cursorh = cursor >> 8; v->cursorl = cursor & 255;
	v->registers[14] = v->cursorh; v->registers[15] = v->cursorl;
	v->x = x; v->y = y;
}

void videoSetChar(Video* v, int x, int y, int code)
{
	if(x < 0 || x >= 80 || y < 0 || y >= 25 || code < 0x20 || code > 0x7e) return;
	unsigned int cell = (displayStart(v) + y * 80 + x) & 0xfff;
	for(unsigned int line = 0; line < 16; line++)
		v->vram[0x20000 + (cell << 4) + line] = line < 9 ? font[(code - 0x20) * 9 + line] & 255 : 0;
}
